import { useState, useEffect } from 'react';

const API_URL = '';

export default function SidePane() {
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    fetch(`${API_URL}/api/side-pane`)
      .then(r => r.json())
      .then(setData);
  }, []);

  if (!data) return null;

  return (
