import { useState, useEffect } from 'react';

const API_URL = '';

export default function Banner() {
  const [promo, setPromo] = useState<string | null>(null);

  useEffect(() => {
    fetch(`${API_URL}/api/banner`)
      .then(r => r.json())
      .then(data => setPromo(data.text || ''));
  }, []);

  if (promo !== null && !promo) return null;

  return (
    <div
